}
_PASSWORD_FIELDS = {
    "min_length": "MinimumLength", "minimum_length": "MinimumLength",
    "require_uppercase": "RequireUppercase", "require_lowercase": "RequireLowercase",
    "require_numbers": "RequireNumbers", "require_symbols": "RequireSymbols",
